import { utilities } from '@cornerstonejs/core';
import { getSegmentation } from '../getSegmentation.js';
import { triggerSegmentationDataModified } from '../triggerSegmentationEvents.js';
import { moveSegmentToPrivateLabelmap as moveSegmentToPrivateLayer } from '../labelmapModel/privateLabelmap.js';
const { DefaultHistoryMemo } = utilities.HistoryMemo;
export function moveSegmentToPrivateLabelmap(segmentationId, segmentIndex, options) {
    const segmentation = getSegmentation(segmentationId);
    if (!segmentation?.representationData.Labelmap) {
        return;
    }
    const layer = moveSegmentToPrivateLayer(segmentation, segmentIndex, {
        moveStepCallback: (step) => {
            if (!options?.recordHistory) {
                return;
            }
            DefaultHistoryMemo.push({
                restoreMemo: (undo) => {
                    if (undo) {
                        step.undo();
                    }
                    else {
                        step.redo();
                    }
                    triggerSegmentationDataModified(segmentationId);
                },
            });
        },
    });
    triggerSegmentationDataModified(segmentationId);
    return layer?.labelmapId;
}
